function postprocessJSON(json, input, helpers) {
  function getRowsAndColumns() {
    return [
      ["row ", helpers.geometry.getAllRows()],
      ["column ", helpers.geometry.getAllColumns()],
    ].flatMap(([type, lines]) =>
      [...lines].slice(1, -1).map((line, i) => ({
        name: `${type}${i+1}`,
        cells: line.slice(1, -1),
      }))
    )
  }
  if (json == undefined) return getRowsAndColumns();


  json.metadata.norowcol = true;
  json.cages.push(
    ...getRowsAndColumns().map(({cells}) => ({
      unique: "true",
      type: "rowcol",
      hidden: "true",
      cells: cells.map(toRC),
    }))
  );

  function toRC(cell) {
    let { x, y } = helpers.cellIds.getCoordsFromId(cell);
    return [y, x];
  }

  let { width:W, height:H } = helpers.cellIds;
  let corners = [[0, 0], [0, W-1], [H-1, 0], [H-1, W-1]];
  for (let [r, c] of corners) {
    delete json.cells[r][c].value;
  }
  let indices = new Set(corners.map(([r, c]) => r * W + c));
  json.metadata.solution = json.metadata.solution?.replace(/./g,
    (digit, index) => indices.has(index) ? "?" : digit
  );
}

let components = postprocessJSON(undefined, undefined, helpers)
  .map(({name, cells}) => new DifferentDigitsComponent(name, cells));

for (let component of components) {
  puzzle.addConstraintComponent(component);
}
